require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/_crm.php';
header('Content-Type: application/json; charset=utf-8');
try{if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')throw new RuntimeException('Método inválido.');crm_csrf_check((string)($_POST['csrf']??''));$cid=crm_company_id();$uid=crm_user_id();if($cid<=0||$uid<=0)throw new RuntimeException('Usuário ou empresa não identificados.');$grid=strtolower(trim((string)($_POST['grid_id']??'')));$defs=['atendimentos'=>['data','nome','telefone','proximo','status','pendencia','tipo','responsavel','solicitacao','acoes']];if(!isset($defs[$grid]))throw new RuntimeException('Grid inválido.');$raw=json_decode((string)($_POST['preferences']??''),true);if(!is_array($raw))throw new RuntimeException('Preferências inválidas.');$allowed=$defs[$grid];$n=crm_grid_preferences_normalize($raw,$allowed);$n['visible']=array_values(array_filter($n['visible'],fn($c)=>$c!=='acoes'));if(!$n['visible'])$n['visible']=array_values(array_filter($allowed,fn($c)=>$c!=='acoes'));$n['visible'][]='acoes';$n['order']=array_values(array_filter($n['order'],fn($c)=>$c!=='acoes'));foreach($allowed as $c)if($c!=='acoes'&&!in_array($c,$n['order'],true))$n['order'][]=$c;$n['order'][]='acoes';$json=json_encode($n,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json===false)throw new RuntimeException('Falha ao serializar preferências.');$st=$pdo->prepare('INSERT INTO app_config(company_id,cfg_key,cfg_json,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE cfg_json=VALUES(cfg_json),updated_at=NOW()');$st->execute([$cid,crm_grid_key($grid,$uid),$json]);echo json_encode(['ok'=>true]);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
